#nullable enable // autogenerated

using MVZ2Logic.UI;
using UnityEngine;

namespace MVZ2.Level.Entities
{
    public class HeightIndicatorController : MonoBehaviour
    {
        public void SetHeight(float value)
        {
            indicatorRenderer.size = new Vector2(indicatorRenderer.size.x, value);
        }
        public void SetColor(Color color)
        {
            indicatorRenderer.color = color;
        }
        [SerializeField]
        private SpriteRendererResolver indicatorRenderer = null!;
    }
}